class BankTransaction extends DataClass implements Insertable<BankTransaction> {
  final int id;
  final DateTime createdAt;
  final DateTime? updatedAt;

  /// Human-readable: BTXN-2025-0001
  final String txnId;

  /// FK → BankAccounts.id
  final int accountId;

  /// Date the transaction was initiated / recorded
  final DateTime txnDate;

  /// Cheque/NEFT actual clearing date (may differ from txnDate)
  final DateTime? valueDate;

  /// CREDIT | DEBIT
  final String type;

  /// See BankTransactionCategory enum values
  final String category;

  /// Always positive — direction determined by [type]
  final double amount;

  /// NEFT | RTGS | IMPS | UPI | CHEQUE | CASH_DEPOSIT | CASH_WITHDRAWAL | CARD
  final String paymentMode;
  final String? chequeNumber;

  /// ISSUED | PRESENTED | CLEARED | BOUNCED
  final String? chequeStatus;
  final DateTime? chequeDate;
  final String? description;

  /// Source record ID: Bill.billNo, SalesOrder.id, etc.
  final String? referenceId;

  /// BILL | ORDER | PURCHASE | MANUAL | SALARY | EXPENSE
  final String? referenceType;

  /// Customer / Supplier / Party name
  final String? partyName;

  /// true = matched with bank statement
  final bool isReconciled;
  final String? reconciliationNote;

  /// true = auto-generated from POS/Booking (non-editable)
  final bool isAutoGenerated;

  /// Soft delete — financial records never hard-deleted
  final bool isVoided;
  final String? voidReason;
