class GirviPayment extends DataClass implements Insertable<GirviPayment> {
  final int id;
  final DateTime createdAt;
  final DateTime? updatedAt;
  final int girviId;

  /// Date this payment was received
  final DateTime paymentDate;

  /// Amount collected in this payment (₹)
  final double amount;

  /// INTEREST | PARTIAL_PRINCIPAL | PARTIAL_INTEREST | FULL_RELEASE | PENALTY
  final String paymentType;

  /// Cash | UPI | NEFT | Bank Transfer | Cheque
  final String paymentMode;

  /// Number of months covered (for interest payments)
  final int? monthsCovered;

  /// Interest period FROM date (for interest payments)
  final DateTime? interestFromDate;

  /// Interest period TO date (for interest payments)
  final DateTime? interestToDate;

  /// Running outstanding balance AFTER this payment
  final double balanceAfter;

  /// Optional receipt/ref number
  final String? receiptNo;

  /// Any remarks
  final String? notes;
  const GirviPayment(
      {required this.id,
      required this.createdAt,
      this.updatedAt,
      required this.girviId,
      required this.paymentDate,
      required this.amount,
      required this.paymentType,
      required this.paymentMode,
      this.monthsCovered,
      this.interestFromDate,
      this.interestToDate,
      required this.balanceAfter,
      this.receiptNo,
      this.notes});
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    if (!nullToAbsent || updatedAt != null) {
      map['updated_at'] = Variable<DateTime>(updatedAt);
    }
    map['girvi_id'] = Variable<int>(girviId);
    map['payment_date'] = Variable<DateTime>(paymentDate);
    map['amount'] = Variable<double>(amount);
    map['payment_type'] = Variable<String>(paymentType);
    map['payment_mode'] = Variable<String>(paymentMode);
    if (!nullToAbsent || monthsCovered != null) {
      map['months_covered'] = Variable<int>(monthsCovered);
    }
    if (!nullToAbsent || interestFromDate != null) {
      map['interest_from_date'] = Variable<DateTime>(interestFromDate);
    }
    if (!nullToAbsent || interestToDate != null) {
      map['interest_to_date'] = Variable<DateTime>(interestToDate);
    }
    map['balance_after'] = Variable<double>(balanceAfter);
    if (!nullToAbsent || receiptNo != null) {
      map['receipt_no'] = Variable<String>(receiptNo);
    }
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    return map;
  }

  GirviPaymentsCompanion toCompanion(bool nullToAbsent) {
    return GirviPaymentsCompanion(
      id: Value(id),
      createdAt: Value(createdAt),
      updatedAt: updatedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(updatedAt),
      girviId: Value(girviId),
      paymentDate: Value(paymentDate),
      amount: Value(amount),
      paymentType: Value(paymentType),
      paymentMode: Value(paymentMode),
      monthsCovered: monthsCovered == null && nullToAbsent
          ? const Value.absent()
          : Value(monthsCovered),
      interestFromDate: interestFromDate == null && nullToAbsent
          ? const Value.absent()
          : Value(interestFromDate),
      interestToDate: interestToDate == null && nullToAbsent
          ? const Value.absent()
          : Value(interestToDate),
      balanceAfter: Value(balanceAfter),
      receiptNo: receiptNo == null && nullToAbsent
          ? const Value.absent()
          : Value(receiptNo),
      notes:
          notes == null && nullToAbsent ? const Value.absent() : Value(notes),
